      t.closest("[data-carousel-prev]") || t.closest("[data-carousel-prev]");
    var nextBtn =
      t.closest("[data-carousel-next]") || t.closest("[data-carousel-next]");
    var dot = t.closest(".carousel__dot") || t.closest(".carousel__dot");

    if (!prevBtn && !nextBtn && !dot) return;
    if (prevBtn && prevBtn.disabled) return;
    if (nextBtn && nextBtn.disabled) return;

