/* ── controllers/code.js ── */
/* HYPERPART: code */
/*
 * code — copy control for the code Hyperpart.
 *
 * Contract (mirrors contracts/code.py DOM_CONTRACT):
 *   [data-code] root
 *   [data-code-copy] optional button — copies .code__source textContent
 *   data-copied on the button while feedback is showing
 *
 * Document-delegated; no per-instance wiring. Clipboard API preferred;
 * falls back to a temporary textarea + execCommand when writeText rejects
 * (insecure origins, permission denials) so the control never fails silently.
 */
(function () {
  "use strict";

  function sourceFor(btn) {
    var root = btn.closest("[data-code]");
    if (!root) return null;
    // Prefer the dedicated source node (inside pre, never the meta bar).
    // Avoid bare "code" / ".code" collisions with the unprefixed root class.
    return (
      root.querySelector(".code__source") ||
      root.querySelector(".code__pre code") ||
      root.querySelector("pre code")
    );
  }

  function execCommandCopy(text) {
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.setAttribute("readonly", "");
    ta.style.position = "fixed";
    ta.style.left = "-9999px";
    ta.style.top = "0";
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    var ok = false;
    try {
      ok = document.execCommand("copy");
    } catch (_err) {
      ok = false;
    }
    document.body.removeChild(ta);
    return ok;
  }

  function writeClipboard(text) {
    if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
      return navigator.clipboard.writeText(text).catch(function () {
        // Permission / insecure-context: fall through to legacy path.
        if (!execCommandCopy(text)) {
          return Promise.reject(new Error("copy failed"));
        }
      });
    }
    return execCommandCopy(text)
      ? Promise.resolve()
      : Promise.reject(new Error("copy failed"));
  }

  function flashCopied(btn) {
    btn.setAttribute("data-copied", "");
    try {
      btn.blur();
    } catch (_e) {
      /* ignore */
    }
    clearTimeout(btn._dzCodeCopyTimer);
    btn._dzCodeCopyTimer = setTimeout(function () {
      btn.removeAttribute("data-copied");
    }, 1600);
  }

  document.addEventListener("click", function (e) {
    var btn = e.target && e.target.closest && e.target.closest("[data-code-copy]");
    if (!btn) return;
    e.preventDefault();
    e.stopPropagation();
    var src = sourceFor(btn);
    if (!src) return;
    var text = src.textContent || "";
    writeClipboard(text).then(
      function () {
        flashCopied(btn);
      },
      function () {
        /* both paths failed — leave UI alone */
      },
    );
  });
})();

/* ── controllers/menubar.js ── */
/* HYPERPART: menubar */
/*
 * menubar — exclusive-open + outside dismiss for native <details> items.
 *
 * Contract:
 *   - root:  `[data-menubar]` (presentation: `.menubar` / `.menubar`)
 *   - item:  `details.menubar__item` or `details.menubar__item`
 *   - open:  one item open at a time inside a root
 *   - dismiss: pointerdown outside root closes all open items; Escape same
 *
 * Native <details> allow multiple open panels and ignore outside clicks;
 * app menubars must not. Progressive enhancement of the gallery partial.
 *
 * Dual-lock: contracts/menubar.py (`data-menubar`).
 */
(function () {
  "use strict";

  var ITEM = "details.menubar__item, details.menubar__item";
  var ROOT =
    "[data-menubar], .menubar, .menubar, [data-menubar]";

  function menubarRoot(el) {
    if (!el || !el.closest) return null;
    return el.closest(ROOT);
  }

  function isItem(el) {
    return el && el.matches && el.matches(ITEM);
  }

  function closeAllIn(root) {
    if (!root) return;
    var siblings = root.querySelectorAll(ITEM);
    for (var i = 0; i < siblings.length; i++) {
      if (siblings[i].open) siblings[i].open = false;
    }
  }

  document.addEventListener(
    "toggle",
    function (evt) {
      var item = evt.target;
      if (!isItem(item) || !item.open) return;
      var root = menubarRoot(item);
      if (!root) return;
      var siblings = root.querySelectorAll(ITEM);
      for (var i = 0; i < siblings.length; i++) {
        if (siblings[i] !== item && siblings[i].open) {
          siblings[i].open = false;
        }
      }
    },
    true,
  );

  document.addEventListener(
    "pointerdown",
    function (evt) {
      var t = evt.target;
      var roots = document.querySelectorAll(ROOT);
      for (var i = 0; i < roots.length; i++) {
        var root = roots[i];
        if (!root.querySelector(ITEM + "[open]")) continue;
        if (root.contains(t)) continue;
        closeAllIn(root);
      }
    },
    true,
  );

  document.addEventListener(
    "keydown",
    function (evt) {
      if (evt.key !== "Escape") return;
      var roots = document.querySelectorAll(ROOT);
      for (var i = 0; i < roots.length; i++) {
        closeAllIn(roots[i]);
      }
    },
    true,
  );
})();

/* ── controllers/navigation-menu.js ── */
/* HYPERPART: navigation-menu */
/*
 * navigation-menu — exclusive-open + outside dismiss for native <details> panels.
 *
 * Contract:
 *   - root:  `[data-navigation-menu]` (presentation: `.navigation-menu`)
 *   - item:  `details.navigation-menu__branch` (or bare `details` under root)
 *   - open:  one panel open at a time inside a root
 *   - dismiss: pointerdown outside root closes open panels; Escape same
 *
 * Native <details> allow multi-open and ignore outside clicks; product nav must not.
 * Progressive enhancement of the gallery partial.
 *
 * Dual-lock: contracts/navigation_menu.py (`data-navigation-menu`).
 */
