  "use strict";

  var ROOT =
    "details.menu, details.menu, details.popover, details.popover";

  /** @type {WeakMap<Element, number>} */
  var timers = new WeakMap();

  function openRoots() {
    return document.querySelectorAll(ROOT);
  }

  /** Gallery unprefixes data-* → data-* on site/; apps keep data-*. */
  function attr(el, dzName, bareName) {
    var v = el.getAttribute(dzName);
    if (v != null) return v;
    return el.getAttribute(bareName);
  }

